function openSeriesEditor(id){const s=state.series.find(x=>x.id===id),members=state.assets.filter(a=>a.seriesID===id);body.innerHTML=`<h2>${s?'编辑系列':'新建系列'}</h2><div class="stack"><label>名称<input id="series-name" value="${esc(s?.title||'')}"></label><label>简介<textarea id="series-about">${esc(s?.introduction||'')}</textarea></label>${s?`<p>系列中有 ${members.length} 件素材。通过素材详情可加入或移出系列。</p><div class="mini-assets">${members.map(a=>`<button type="button" class="mini-asset" data-detail="${a.id}">${imgTag(a)}<span>${esc(a.title)}</span></button>`).join('')}</div>`:''}<button type="button" class="btn primary" id="series-save">保存系列</button></div>`;modal.showModal();body.querySelector('#series-save').onclick=async()=>{const title=body.querySelector('#series-name').value.trim();if(!title){toast('请填写系列名称');return;}const value=s||{id:uid(),createdAt:new Date().toISOString()};value.title=title;value.introduction=body.querySelector('#series-about').value;value.updatedAt=new Date().toISOString();await db.put('series',value);if(!s)state.series.push(value);modal.close();render();};body.querySelectorAll('[data-detail]').forEach(el=>el.onclick=()=>{modal.close();openDetail(el.dataset.detail);});}
