function saveActiveImportRecord(){const rec=state.importRecords[state.importIndex];if(!rec)return;Object.assign(rec,{bitmap:state.importBitmap,file:state.importFile,url:state.importURL,box:structuredClone(state.importBox),corners:state.paperCorners?structuredClone(state.paperCorners):null,correctedBitmap:state.correctedBitmap,correctedURL:state.correctedURL,candidates:state.importCandidates||[],candidateURLs:state.importCandidateURLs||[],selection:[...(state.importCandidateSelection||[])],wholePaper:state.wholePaper,paperSize:state.paperSize,paperOrientation:state.paperOrientation,balanceLight:state.balanceLight,customImportWidth:state.customImportWidth,customImportHeight:state.customImportHeight});}
async function switchImportRecord(index,skipSave=false){if(!skipSave)saveActiveImportRecord();const rec=state.importRecords[index];if(!rec)return;state.importIndex=index;state.importFile=rec.file;state.importBitmap=rec.bitmap||await createImageBitmap(rec.file);state.importURL=rec.url;state.importBox=rec.box||{x:0,y:0,w:1,h:1};state.paperCorners=rec.corners||await suggestPaperCorners(state.importBitmap).catch(()=>null);state.correctedBitmap=rec.correctedBitmap||null;state.correctedURL=rec.correctedURL||null;state.importCandidates=rec.candidates||[];state.importCandidateURLs=rec.candidateURLs||[];state.importCandidateSelection=new Set(rec.selection||[]);state.wholePaper=rec.wholePaper??state.preferences.wholePaper;state.paperSize=rec.paperSize||state.preferences.paperSize;state.paperOrientation=rec.paperOrientation||state.preferences.orientation;state.balanceLight=rec.balanceLight??state.preferences.balanceLight;state.customImportWidth=rec.customImportWidth||state.preferences.customPaperWidth||210;state.customImportHeight=rec.customImportHeight||state.preferences.customPaperHeight||297;render();if(!state.importCandidates.length&&state.importStep==='inspect')await previewCrop();}
