async function printPage(){const d=current(),canvas=await rasterize(d,2),url=canvas.toDataURL('image/png');const child=window.open('','_blank');if(!child){toast('请允许打开打印预览窗口');return;}child.document.write(`<html><head><title>${esc(state.activeProject.title)}</title><style>@page{size:A4;margin:0}body{margin:0}img{width:100%;height:auto}</style></head><body><img src="${url}" onload="window.print()"></body></html>`);child.document.close();}
async function rasterize(d,scale){const canvas=document.createElement('canvas');canvas.width=Math.round(d.canvas.width*scale);canvas.height=Math.round(d.canvas.height*scale);const ctx=canvas.getContext('2d');ctx.scale(scale,scale);ctx.fillStyle=d.paperColor;ctx.fillRect(0,0,d.canvas.width,d.canvas.height);if(d.paperPattern!=='plain'){ctx.strokeStyle='#c5d3c9';ctx.lineWidth=1;for(let x=24;x<d.canvas.width;x+=28){if(d.paperPattern==='grid'){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,d.canvas.height);ctx.stroke();}}for(let y=28;y<d.canvas.height;y+=28){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(d.canvas.width,y);ctx.stroke();}}
for(const e of editorEntry(d)){const i=e.value;ctx.save();ctx.translate(i.x,i.y);ctx.rotate((i.rotation||0)*Math.PI/180);ctx.globalAlpha=i.opacity??1;if(e.kind==='material'){const a=asset(i.assetID),src=a&&image(a.blobId);if(src){const im=new Image();im.src=src;await im.decode().catch(()=>{});if(im.naturalWidth){ctx.scale(i.isFlippedHorizontally?-1:1,1);const crop=i.cropRect||{x:0,y:0,width:1,height:1};ctx.drawImage(im,crop.x*im.naturalWidth,crop.y*im.naturalHeight,crop.width*im.naturalWidth,crop.height*im.naturalHeight,-i.width/2,-i.height/2,i.width,i.height);}}}else if(e.kind==='shape'){ctx.fillStyle=i.fill||'transparent';ctx.strokeStyle=i.stroke||'transparent';ctx.lineWidth=i.lineWidth||2;if(i.vectorPaths?.length){for(const path of i.vectorPaths){ctx.beginPath();path.forEach(([x,y],n)=>n?ctx.lineTo((x-.5)*i.width,(y-.5)*i.height):ctx.moveTo((x-.5)*i.width,(y-.5)*i.height));ctx.closePath();ctx.fill();if(i.lineWidth&&i.stroke)ctx.stroke();}}else if(i.kind==='ellipse'){ctx.beginPath();ctx.ellipse(0,0,i.width/2,i.height/2,0,0,Math.PI*2);ctx.fill();ctx.stroke();}else{ctx.fillRect(-i.width/2,-i.height/2,i.width,i.height);ctx.strokeRect(-i.width/2,-i.height/2,i.width,i.height);}}else{ctx.fillStyle=i.color;ctx.font=`${i.bold?'bold ':''}${i.fontSize}px ${i.style==='hand'?'"Kaiti SC",STKaiti,cursive':i.style==='serif'?'serif':'sans-serif'}`;ctx.textAlign=i.alignment||'left';const left=ctx.textAlign==='center'?0:ctx.textAlign==='right'?i.width/2:-i.width/2;i.content.split('\n').forEach((line,n)=>ctx.fillText(line,left,-i.height/2+i.fontSize+(i.lineHeight||i.fontSize*1.3)*n));}ctx.restore();}
for(const line of d.strokes||[]){ctx.globalAlpha=line.opacity??1;ctx.strokeStyle=line.color||'#385b49';ctx.lineWidth=line.width||3;ctx.beginPath();line.points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.stroke();ctx.globalAlpha=1;}return canvas;}
fileInput.onchange=async()=>{const files=[...(fileInput.files||[])].filter(f=>f.type.startsWith('image/')).slice(0,Math.max(0,12-state.importRecords.length));if(!files.length)return;try{saveActiveImportRecord();const start=state.importRecords.length;for(const file of files)state.importRecords.push({file,url:URL.createObjectURL(file),confirmed:false,selectedCandidates:[],selection:[],candidates:[]});state.importStep='inspect';state.route='import';await switchImportRecord(start,true);}catch(e){console.error(e);toast('图片无法读取');}finally{fileInput.value='';}};
